// src/game/prg/data/store/RenderQueues.ts
function consumeNtBuffer(view) {
  if (view.ntBufferBusy) return [];
  const pos = view.ntBufferPos;
  if (pos === 0) return [];
  const buf = view.ntBuffer;
  const out = [];
  let x = 0;
  while (x + 3 <= pos) {
    const b0 = buf[x] & 255;
    if (b0 === 0) break;
    const vertical = (b0 & 128) !== 0;
    const count = vertical ? b0 & 63 : b0;
    if (x + 3 + count > pos) break;
    const addr = buf[x + 2] << 8 | buf[x + 1];
    const data = Array.from(buf.subarray(x + 3, x + 3 + count));
    out.push({ vertical, ntAddr: addr & 16383, data });
    x += 3 + count;
  }
  return out;
}
function appendNtBuffer(view, entry) {
  const pos = view.ntBufferPos;
  const totalLen = 3 + entry.data.length;
  if (pos + totalLen > 64) return false;
  const buf = view.ntBuffer;
  const ctrlByte = (entry.vertical ? 128 : 0) | entry.data.length & (entry.vertical ? 63 : 255);
  buf[pos] = ctrlByte;
  buf[pos + 1] = entry.ntAddr & 255;
  buf[pos + 2] = entry.ntAddr >> 8 & 255;
  for (let i = 0; i < entry.data.length; i++) buf[pos + 3 + i] = entry.data[i] & 255;
  buf[pos + totalLen] = 0;
  view.setNtBufferPos(pos + totalLen);
  return true;
}

