// src/game/prg/code/story/ScriptEngine.ts
var ScriptEngine = class {
  constructor(store, loader, indirect = null) {
    this.store = store;
    this.loader = loader;
    this.indirect = indirect;
  }
  /**
   * 装载并启动一段脚本
   * 对应 asm `LDA $00ED; STX $00ED; LDA ($004D),Y`：装载段流 → 初始化上下文。
   */
  start(scriptId) {
    const seg = this.loader.loadSegment(scriptId);
    if (!seg) return null;
    return {
      ip: 0,
      stack: [],
      waitFrames: 0,
      waitingInput: false,
      segmentId: scriptId,
      finished: seg.bytes.length === 0,
      bytes: seg.bytes
    };
  }
  /**
   * 装载指定 IP 起点的子段（Call/Return 用）
   * 对应 asm $9201-$923E 的子段调用路径。
   */
  startAt(bytes, startIp) {
    return {
      ip: startIp & 65535,
      stack: [],
      waitFrames: 0,
      waitingInput: false,
      segmentId: -1,
      finished: bytes.length === 0,
      bytes
    };
  }
  /**
   * 推进一步（执行一帧脚本）
   * 返回：true = 仍在运行（VM 还想继续）；false = 本帧已饱和。
   * 等价 asm dispatch loop $90E4-$94D2。
   */
  step(ctx) {
    if (ctx.finished) return false;
    if (ctx.waitFrames > 0) {
      ctx.waitFrames--;
      return ctx.waitFrames > 0;
    }
    if (ctx.waitingInput) return false;
    while (ctx.ip < ctx.bytes.length) {
      const opcode = ctx.bytes[ctx.ip] & 255;
      ctx.ip++;
      if (opcode === 13 /* EndSegment */) {
        ctx.finished = true;
        return false;
      }
      if (opcode === 255 /* EndScript */) {
        ctx.finished = true;
        return false;
      }
      const read = () => {
        if (ctx.ip >= ctx.bytes.length) return 0;
        const v = ctx.bytes[ctx.ip] & 255;
        ctx.ip++;
        return v;
      };
      let handler = getHandler(opcode);
      let isIndirect = false;
      let indirectIdx = 0;
      if (!handler) {
        const cls = classifyOpcode(opcode);
        if (cls.direct) {
          if (ctx.ip < ctx.bytes.length) ctx.ip++;
          continue;
        }
        if (!this.indirect) {
          if (ctx.ip + 1 < ctx.bytes.length) ctx.ip += 2;
          continue;
        }
        isIndirect = true;
        indirectIdx = cls.index;
        if (!handler) {
          if (ctx.ip + 1 < ctx.bytes.length) ctx.ip += 2;
          continue;
        }
      }
      const cont = handler(ctx, read);
      if (cont === false) return true;
      if (ctx.waitFrames > 0) return true;
      if (ctx.waitingInput) return false;
    }
    ctx.finished = true;
    return false;
  }
  /**
   * 缺省间接解析器：从 BANK18_DATA_TABLES 中读出 16-bit 入口（reserve placeholder）。
   * 真实项目应使用 StoryController 注入专用解析器。
   */
  static defaultIndirectFromBank18(_opcodeMinusBase) {
    return 0;
  }
  static {
    /**
     * 范围检查常量（暴露供测试/调试用）。
     */
    this.DIRECT_MAX = OPCODE_DIRECT_MAX;
  }
  static {
    this.INDIRECT_BASE = OPCODE_INDIRECT_BASE;
  }
};

