var SEGMENT_SIZE = 4096;
var SEGMENT_BYTES = (() => {
  const out = [];
  for (let i = 0; i < BANK18_DATA_TABLES.length; i += SEGMENT_SIZE) {
    out.push(BANK18_DATA_TABLES.slice(i, i + SEGMENT_SIZE));
  }
  return out;
})();
var ScriptLoader = class {
  constructor(store) {
    this.store = store;
  }
  /** 按段 ID 装载（V0.4 已实现：返回 BANK18 切分段） */
  loadSegment(scriptId) {
    const id = scriptId & 255;
    const seg = SEGMENT_BYTES[id];
    if (!seg) return null;
    return { id, bytes: seg };
  }
  /** 全部段清单（按 BANK18 切片） */
  listSegments() {
    const ids = [];
    for (let i = 0; i < SEGMENT_BYTES.length; i++) {
      if (SEGMENT_BYTES[i].length > 0) ids.push(i);
    }
    return ids;
  }
  /** 段字节长度 */
  segmentLength(scriptId) {
    return SEGMENT_BYTES[scriptId & 255]?.length ?? 0;
  }
};

// src/game/prg/code/story/CharMap.ts
var CharMap = class {
  constructor() {
    /** 字符 → tile 号映射 */
    this.map = /* @__PURE__ */ new Map();
    this.initDefault();
  }
  /**
   * 默认初始化：ASCII 32..127 映射到对应 tile 偏移。
   * 真实项目应从 BANK19 字符索引表覆盖。
   */
  initDefault() {
    this.map.set(32, 0);
    for (let i = 33; i <= 47; i++) this.map.set(i, i - 32);
    for (let i = 48; i <= 57; i++) this.map.set(i, 16 + (i - 48));
    for (let i = 58; i <= 64; i++) this.map.set(i, 26 + (i - 58));
    for (let i = 65; i <= 90; i++) this.map.set(i, 33 + (i - 65));
    for (let i = 91; i <= 96; i++) this.map.set(i, 59 + (i - 91));
    for (let i = 97; i <= 122; i++) this.map.set(i, 65 + (i - 97));
  }
  /** 注册单条映射（供数据表注入） */
  register(charCode, tile) {
    this.map.set(charCode & 255, tile & 255);
  }
  /** 批量注册（剧情脚本 / 字幕表 启动时一次性注入） */
  registerTable(entries) {
    for (const [c, t] of entries) this.register(c, t);
  }
  /** 字符 → tile（未注册返回 0 空格 tile） */
  toTile(charCode) {
    return this.map.get(charCode & 255) ?? 0;
  }
  /** 一段文本 → tile 序列 */
  toTiles(text) {
    return text.map((c) => this.toTile(c));
  }
  /** 注册数量 */
  get size() {
    return this.map.size;
  }
};

